<template>
  <div class="raw-duties" :class="{'single-view':!context.canConfigure && !context.canManageMembers}" v-loading="loading">
    <el-alert v-if="context.preview" title="本地预览 · 模拟人员与材料" type="warning" :closable="false" show-icon />
    <el-tabs v-model="tab">
      <el-tab-pane label="周履职" name="reports">
        <div v-if="context.isReviewer" class="duty-toolbar"><label>周次 <el-date-picker :model-value="week" type="date" value-format="YYYY-MM-DD" :clearable="false" :disabled="loading || busy" @update:model-value="changeWeek" /></label><span>{{ period.start }} 至 {{ period.end }}</span><el-input v-if="context.isReviewer" v-model="search" placeholder="搜索姓名、岗位或班组" clearable class="duty-search" /><el-button v-if="context.isReviewer" text aria-label="刷新履职记录" title="刷新履职记录" :disabled="loading || busy" @click="refresh"><el-icon><Refresh /></el-icon></el-button><el-button v-if="ownMember" class="desktop-fill-button" type="primary" :disabled="busy" @click="openOwn">填写我的本周材料</el-button><el-button v-if="context.isReviewer" class="desktop-batch-button" :disabled="!exportIds.length || busy" :loading="exporting" @click="exportBatch">导出本周材料包（{{ exportIds.length }}）</el-button></div>
        <div v-if="context.isReviewer" class="duty-metrics"><article v-for="m in metrics" :key="m.label" :style="{'--metric-color':m.color}"><span>{{ m.label }}</span><strong>{{ m.value }}</strong></article></div>
        <template v-if="context.isReviewer"><div class="duty-list panel personnel-summary"><div class="list-caption"><strong>{{ context.isReviewer ? '人员填报情况' : '我的周材料' }}</strong><span v-if="context.isReviewer && selection.length">已选 {{ selection.length }} 人 · 可导出 {{ exportIds.length }} 份</span></div>
          <el-alert v-if="error" :title="error" type="error" :closable="false" />
          <el-table :data="filtered" row-key="userId" @selection-change="selection = $event">
            <el-table-column v-if="context.isReviewer" type="selection" width="45" />
            <el-table-column prop="name" label="姓名" min-width="105" /><el-table-column prop="team" label="班组 / 工段" min-width="110" />
            
            
            <el-table-column label="履职情况" min-width="330"><template #default="{row}"><div class="row-duty-overview"><strong>已完成 {{ row.itemOverview?.done ?? '—' }} / {{ row.itemOverview?.total ?? '—' }} 项</strong><span>异常 {{ row.itemOverview?.abnormal ?? 0 }} · 未履职 {{ row.itemOverview?.incomplete ?? '—' }} · 待填写 {{ row.itemOverview?.missing ?? '—' }}</span><small>待补材料 {{ row.itemOverview?.evidence ?? '—' }}<template v-if="row.itemOverview?.working || row.itemOverview?.exempt"> · 历史进行中 {{ row.itemOverview?.working || 0 }} · 未发生/不适用 {{ row.itemOverview?.exempt || 0 }}</template></small></div></template></el-table-column>
            <el-table-column label="材料状态" min-width="100"><template #default="{row}"><el-tag :type="tagType(row.status)" effect="light">{{ labels[row.status] }}</el-tag></template></el-table-column>
            <el-table-column label="最后更新" min-width="160"><template #default="{row}">{{ formatTime(row.updatedAt) }}</template></el-table-column>
            <el-table-column label="操作" min-width="155" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="busy || (!row.canRead && row.userId !== context.userId)" @click="openRow(row)">{{ row.userId === context.userId && ['draft','returned','empty'].includes(row.status) ? '填写材料' : row.canRead ? '查看' : '等待提交' }}</el-button><el-button v-if="row.reportId && row.canRead && row.status!=='draft'" link :disabled="busy" @click="download(row.reportId)">导出</el-button></template></el-table-column>
            <template #empty><el-empty description="暂无已分配的履职人员，请由系统管理员配置人员和负责人。" /></template>
          </el-table>
        </div>
        <section class="mobile-personnel-summary"><h3>人员填报情况</h3><article v-for="row in filtered" :key="row.userId" class="panel"><header><div><strong>{{row.name}}</strong><small>{{row.team||'未分班组'}}</small></div><el-tag :type="tagType(row.status)">{{labels[row.status]}}</el-tag></header><div class="mobile-completion"><strong>已完成 {{row.itemOverview?.done ?? '—'}} / {{row.itemOverview?.total ?? '—'}} 项</strong><span>异常 {{row.itemOverview?.abnormal ?? 0}} · 未履职 {{row.itemOverview?.incomplete ?? '—'}}</span><span>待填写 {{row.itemOverview?.missing ?? '—'}} · 待补材料 {{row.itemOverview?.evidence ?? '—'}}</span><span>未发生/不适用 {{row.itemOverview?.exempt ?? '—'}}</span></div><footer><small>{{formatTime(row.updatedAt)}}</small><el-button v-if="row.reportId && row.canRead && row.status!=='draft'" :disabled="busy" @click="download(row.reportId)">导出</el-button><el-button type="primary" :disabled="busy || (!row.canRead && row.userId!==context.userId)" @click="openRow(row)">{{row.canRead?'查看':'等待提交'}}</el-button></footer></article><el-empty v-if="!filtered.length" description="暂无履职人员" /></section>
      </template>
        <section v-if="ownMember && !context.isReviewer" class="owner-workspace">
          <div class="fill-toolbar panel"><label>填报日期<el-date-picker :model-value="selectedDate || today" value-format="YYYY-MM-DD" :clearable="false" :disabled="busy" :disabled-date="d=>localDate(d)>today" @update:model-value="changeFillDate" /></label><label v-if="cadenceMode">当日上班情况<el-radio-group :model-value="calendar[selectedDate]" :disabled="!editable || busy" @update:model-value="setDayState"><el-radio-button value="work">上班</el-radio-button><el-radio-button value="rest">休息</el-radio-button></el-radio-group></label><el-button text :disabled="busy" aria-label="刷新我的履职" title="刷新我的履职" @click="reloadOwn"><el-icon><Refresh /></el-icon></el-button></div>
          <nav class="owner-tabs"><button :class="{active:ownerTab==='fill'}" @click="ownerTab='fill'">我要填报</button><button :class="{active:ownerTab==='records'}" @click="ownerTab='records'">我的记录</button></nav>
          <template v-if="record && ownerTab==='fill'"><div v-if="cadenceMode" class="fill-status panel"><strong>{{ calendar[selectedDate]==='rest'?'当日休息':'当日待填 '+ownerPending+' 项' }}</strong><span>{{ selectedDate }} · <b class="completed-count">已完成 {{ ownerDailyDone }} / {{ ownerDailyTotal }} 项</b><b v-if="ownerDailyAbnormal" class="incomplete-result"> · 异常 {{ ownerDailyAbnormal }} 项</b></span><span>本周待填 <b class="pending-count">{{ ownerPeriodPending('每周') }}</b> 项 · 本月待填 <b class="pending-count">{{ ownerPeriodPending('每月') }}</b> 项</span></div>
            <el-alert v-if="cadenceMode && calendar[selectedDate]!=='work'" :title="calendar[selectedDate]==='rest'?'当日休息，每周和每月事项仍按实际执行情况记录':'请先选择当日上班或休息'" type="info" :closable="false" />
            <section v-for="group in ownerGroups" :key="group.name" class="fill-category panel"><header><strong>{{group.name}}</strong><small>{{group.items.filter(e=>['missing','evidence'].includes(dutyState(itemCheck(e)))).length}} 项待填</small></header><article v-for="item in group.items" :key="item.id"><div><h3>{{item.title}}</h3><small>{{item.frequency==='每班'?'每日':item.frequency}} · {{item.evidence}}</small><span :class="{'filled-result':dutyState(itemCheck(item))==='done','incomplete-result':itemCheck(item).result==='异常'}">{{ownerItemLabel(item)}}</span></div><el-button type="primary" :disabled="busy || cadenceMode && item.frequency==='每班' && calendar[selectedDate]!=='work'" @click="openOwnerItem(item)">{{editable?'填报':'查看'}}</el-button></article></section>
          </template><template v-else-if="record"><details v-if="record.cadence?.legacyChecks?.length" class="legacy-records"><summary>历史周材料</summary><p v-for="c in record.cadence.legacyChecks" :key="c.dutyId">{{record.template.entries.find(e=>e.id===c.dutyId)?.title}} · {{c.result}} · {{c.note}}</p></details><RawDutyWeekTable :entries="record.template.entries" :checks="Object.values(checks)" :calendar="calendar" :start="record.week_start" :today="today" :legacy="!cadenceMode" :name="record.identity.name" @choose="chooseCell" /><RawDutySummary v-model="summary" :editable="editable" :busy="busy" :generating="generatingSummary" :error="summaryError" :quota="summaryQuota" @update:model-value="dirty=true" @generate="generateWeeklySummary" /></template>
          <div v-if="record && (ownerTab==='records' || dirty)" class="owner-submit panel"><span>{{labels[record.status]}}</span><el-button v-if="editable" :disabled="busy || !dirty" @click="saveReport(false)">保存草稿</el-button><el-button v-if="ownerTab==='records' && editable" type="primary" :disabled="busy" @click="saveReport(true)">提交本周材料</el-button><el-button v-if="ownerTab==='records' && isOwner && record.status==='submitted'" :disabled="busy" @click="act('withdraw')">撤回修改</el-button><el-button v-if="ownerTab==='records' && record.id" :disabled="busy" @click="download(record.id)">导出</el-button></div>
        </section>
      </el-tab-pane>
      <el-tab-pane v-if="context.canManageMembers" label="人员与负责人" name="members">
        <el-table :data="memberDrafts" row-key="user_id"><el-table-column prop="name" label="姓名" width="110" /><el-table-column label="履职岗位" min-width="125"><template #default="{row}"><el-input v-model="row.position" maxlength="50" placeholder="如：工段长" /></template></el-table-column><el-table-column label="班组 / 工段" min-width="130"><template #default="{row}"><el-input v-model="row.team" maxlength="80" /></template></el-table-column><el-table-column label="负责人" min-width="140"><template #default="{row}"><el-select v-model="row.reviewerId" placeholder="选择负责人"><el-option v-for="u in context.users.filter(u => Number(u.id) !== row.user_id)" :key="u.id" :label="u.name" :value="Number(u.id)" /></el-select></template></el-table-column><el-table-column label="职责模板" min-width="200"><template #default="{row}"><el-select v-model="row.templateId" placeholder="选择职责模板"><el-option v-for="t in availableTemplates" :key="t.id" :value="t.id" :label="t.title" /></el-select></template></el-table-column><el-table-column label="启用" width="80"><template #default="{row}"><el-switch v-model="row.active" /></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button type="primary" link :disabled="busy" @click="saveMember(row)">保存分配</el-button></template></el-table-column></el-table>
      </el-tab-pane>
      <el-tab-pane v-if="context.canConfigure" label="职责模板" name="templates">
        
        <div class="duty-toolbar template-toolbar"><label>职责模板 <el-select :model-value="templateId || undefined" placeholder="选择已有模板" :disabled="editingTemplate || busy" @change="loadTemplate"><el-option v-for="t in availableTemplates" :key="t.id" :value="t.id" :label="t.title" /></el-select></label><template v-if="!editingTemplate"><el-button v-if="templateId" type="primary" :disabled="busy" @click="beginTemplateEdit">编辑模板</el-button><el-button :disabled="busy" @click="newTemplate">新建模板</el-button><el-button v-if="templateId" :disabled="busy" @click="renameTemplate">重命名</el-button><el-button v-if="templateId" type="danger" plain :disabled="busy" @click="deleteTemplate">删除</el-button></template><template v-else><span class="template-edit-name">正在编辑：{{templateDraft.title}}</span><el-button :disabled="busy" @click="addDuty">增加职责</el-button><el-button type="primary" :disabled="busy" @click="saveTemplate">{{ templateTargetId?'保存修改':'保存模板' }}</el-button><el-button :disabled="busy" @click="loadTemplate(templateId)">取消</el-button></template></div>
        <el-table :data="templateDraft.entries"><el-table-column type="index" width="45" /><el-table-column label="工作分类" width="130"><template #default="{row}"><el-input :disabled="!editingTemplate" v-model="row.category" maxlength="50" /></template></el-table-column><el-table-column label="工作内容" min-width="310"><template #default="{row}"><el-input :disabled="!editingTemplate" v-model="row.title" type="textarea" :autosize="{minRows:2,maxRows:5}" maxlength="600" /></template></el-table-column><el-table-column label="频次" width="130"><template #default="{row}"><el-select :disabled="!editingTemplate" v-model="row.frequency"><el-option v-for="v in frequencies" :key="v" :value="v" :label="v" /></el-select></template></el-table-column><el-table-column label="输出要求" min-width="170"><template #default="{row}"><el-input :disabled="!editingTemplate" v-model="row.evidence" maxlength="150" /></template></el-table-column><el-table-column v-if="editingTemplate" label="操作" width="110" align="center" class-name="template-actions"><template #default="{ $index }"><el-button link type="danger" @click="templateDraft.entries.splice($index,1)">移除</el-button></template></el-table-column></el-table>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="showItem" :width="'min(760px, calc(100vw - 24px))'" align-center append-to-body :close-on-click-modal="false" :before-close="closeItem" destroy-on-close class="duty-item-dialog"><template #header><div class="item-dialog-heading"><strong>{{activeEntry?.title}}</strong><span>{{cadenceMode ? selectedDate+' · '+(activeEntry?.frequency==='每班'?'每日履职':activeEntry?.frequency) : '原周材料（未按日拆分）'}}</span></div></template><div v-for="group in groups" :key="group.name" class="duty-group">
          <details v-for="item in group.items" :key="item.id" class="duty-item" :data-duty-id="item.id" :open="expandedDuties.includes(item.id)"><summary class="duty-item-summary"><div class="item-title"><span class="item-number">{{ item.index + 1 }}</span><strong>{{ item.title }}</strong></div><div class="item-status"><span>{{ item.frequency }}</span><span :class="{'filled-result':itemCheck(item).result==='已完成','pending-result':itemCheck(item).result==='进行中','incomplete-result':['未完成','异常'].includes(itemCheck(item).result)}">{{ itemCheck(item).result || '待填写' }}</span><span v-if="dutyState(itemCheck(item))==='evidence'" class="incomplete-result">待补说明、图片或日期</span><span v-if="itemCheck(item).photoIds.length">{{ itemCheck(item).photoIds.length }} 张图片</span></div></summary><div class="duty-item-body"><p class="evidence-note">{{ item.evidence }}</p>
            <label class="field-label">{{ cadenceMode && item.frequency==='每班' ? '当日结果' : cadenceMode && item.frequency==='每月' ? '本月结果' : '本周结果' }}<el-select v-model="itemCheck(item).result" :disabled="!canEditItem(item) || busy" placeholder="选择结果" @change="dirty=true"><el-option v-for="r in context.results" :key="r" :label="r" :value="r" /></el-select></label>
            <el-alert v-if="itemCheck(item).shared" :title="'本月已于 '+itemCheck(item).recordDate+' 完成，材料来自 '+itemCheck(item).originWeek+' 周'" type="success" :closable="false" /><small v-if="itemCheck(item).recordedAt" class="muted">记录时间：{{ formatTime(itemCheck(item).recordedAt) }}<span v-if="itemCheck(item).firstRecordedAt"> · 首次记录：{{ formatTime(itemCheck(item).firstRecordedAt) }}</span></small><label class="field-label">{{ itemCheck(item).result==='异常' ? '异常原因（必填）' : '履职说明（选填）' }}<el-input v-model="itemCheck(item).note" type="textarea" :autosize="{minRows:3,maxRows:9}" maxlength="4000" :disabled="!canEditItem(item) || busy" :placeholder="itemCheck(item).result==='异常' ? '请说明发现的问题、异常原因或影响' : '可补充实际完成情况'" @input="dirty=true" /></label>
            <div class="item-photo-strip"><el-image v-for="id in itemCheck(item).photoIds" :key="id" :src="photoUrls[id]" fit="cover" :preview-src-list="itemCheck(item).photoIds.map(id=>photoUrls[id]).filter(Boolean)" preview-teleported /><el-upload v-if="canEditItem(item)" :show-file-list="false" accept="image/jpeg,image/png,image/webp" :http-request="options=>uploadPhoto(options,item.id)" :disabled="busy"><el-button :disabled="busy" :loading="uploading">＋ 添加照片</el-button></el-upload></div>
            <details v-if="record.photos.length" class="optional-fields"><summary>{{ editable ? '引用本周其他图片' : '关联图片' }}</summary><el-checkbox-group v-model="itemCheck(item).photoIds" :disabled="!canEditItem(item) || busy" @change="dirty=true"><el-checkbox v-for="p in record.photos.filter(p=>p.report_id===record.id)" :key="p.id" :value="p.id" :label="p.id">图片 {{ p.id }}</el-checkbox></el-checkbox-group></details>
            <label v-if="cadenceMode && item.frequency!=='每班'" class="field-label">实际执行日期（必填）<el-date-picker v-model="itemCheck(item).recordDate" value-format="YYYY-MM-DD" :disabled="!canEditItem(item) || busy" :disabled-date="date=>outsideExecutionDate(date,item)" @change="dirty=true" /></label><details class="optional-fields" :open="itemCheck(item).result==='异常' || !!itemCheck(item).action"><summary>{{ itemCheck(item).result==='异常' ? '异常处理进展（选填）' : '处理进展（选填）' }}</summary><label v-if="!cadenceMode" class="field-label">记录日期<el-date-picker v-model="itemCheck(item).recordDate" value-format="YYYY-MM-DD" :disabled="!canEditItem(item) || busy" :disabled-date="outsideWeek" @change="dirty=true" /></label><label class="field-label">处理进展<el-input v-model="itemCheck(item).action" type="textarea" :autosize="{minRows:2,maxRows:6}" :disabled="!canEditItem(item) || busy" maxlength="4000" @input="dirty=true" /></label></details>
          </div></details>
        </div>
        <template #footer><div class="item-dialog-footer"><template v-if="activeEntry && canEditItem(activeEntry)"><el-button :disabled="busy" @click="saveItem(false)">保存并返回</el-button><el-button v-if="nextItem" type="primary" :disabled="busy" @click="saveItem(true)">保存并填下一项</el-button></template><el-button v-else :disabled="busy" @click="showItem=false">返回</el-button></div></template></el-dialog>
    <el-dialog v-model="showReport" :width="dialogWidth" align-center :close-on-click-modal="false" :before-close="closeReport" destroy-on-close class="duty-dialog">
      <template #header><div v-if="record" class="drawer-heading"><strong>{{ record.identity.name }} · {{ labels[record.status] }}</strong><span>{{ record.week_start }} 至 {{ reportEnd }}</span><div class="report-progress"><el-progress :percentage="reportStats.progress.total?Math.round(reportStats.progress.ready/reportStats.progress.total*100):0" :show-text="false" color="#6263a8" /><small>材料齐备 {{ reportStats.progress.ready }}/{{ reportStats.progress.total }} 项</small></div><template v-if="cadenceMode"><div class="attendance-choice"><span>{{ selectedDate }} · {{ calendar[selectedDate]==='work'?'上班':calendar[selectedDate]==='rest'?'休息':'待确认' }}</span><el-radio-group v-if="editable" :model-value="calendar[selectedDate]" :disabled="busy" @update:model-value="setDayState"><el-radio-button value="work">上班</el-radio-button><el-radio-button value="rest">休息</el-radio-button></el-radio-group><small>点击表格中的日期格查看或填写</small></div></template><div v-else class="legacy-mode"><span>原周材料已保留；未明确日期的内容不计入每日完成</span></div><small v-if="isOwner && ['draft','returned'].includes(record.status)" class="submission-note">{{ reportStats.calendarPending ? '请确认本周每天上班或休息（'+reportStats.calendarPending+'天待确认）' : reportStats.progress.ready===reportStats.progress.total ? '材料已齐备，请提交本周材料' : '补齐待填事项和验证材料后提交' }}</small></div></template>
      <template v-if="record">
        <el-alert v-if="record.feedback" :title="'负责人意见：'+record.feedback" :type="record.status === 'returned' ? 'warning' : 'info'" :closable="false" />
        <details v-if="record.cadence?.legacyChecks" class="legacy-records"><summary>原历史周汇总（保留，未拆为每日记录）</summary><p v-for="c in record.cadence.legacyChecks" :key="c.dutyId">{{ record.template.entries.find(e=>e.id===c.dutyId)?.title }} · {{ c.result }} · {{ c.note }}</p></details><details v-if="record.photos.length" class="material-panel photo-library"><summary>本周图片（{{ record.photos.length }}）</summary>
          <div v-if="record.photos.length" class="material-grid"><div v-for="p in record.photos" :key="p.id" class="material-tile"><el-image v-if="photoUrls[p.id]" :src="photoUrls[p.id]" fit="cover" :preview-src-list="Object.values(photoUrls)" preview-teleported /><span>材料 {{ p.id }}</span><el-button v-if="editable && !record.submitted_at && p.report_id===record.id" link type="danger" :disabled="busy" @click="removePhoto(p.id)">删除</el-button></div></div><p v-else class="muted">可上传现场照片或工作截图，也可先填写文字说明。</p>
        </details>
        <RawDutyWeekTable :entries="record.template.entries" :checks="Object.values(checks)" :calendar="calendar" :start="record.week_start" :today="today" :legacy="!cadenceMode" :name="record.identity.name" @choose="chooseCell" />
        <el-alert v-if="cadenceMode && frequencyFilter==='每班' && calendar[selectedDate]!=='work'" :title="calendar[selectedDate]==='rest'?'当日休息，不计入应填履职事项':(editable?'请先确认当日上班或休息':'填报人尚未确认当日上班情况')" :closable="false" type="info" /><RawDutySummary v-model="summary" :editable="editable" :busy="busy" :generating="generatingSummary" :error="summaryError" :quota="summaryQuota" @update:model-value="dirty=true" @generate="generateWeeklySummary" />
        <div v-if="canReview" class="material-panel"><h3>负责人意见</h3><el-input v-model="feedback" type="textarea" :rows="2" maxlength="4000" placeholder="退回补充或重新打开时必须填写原因" /></div>
        <details class="event-list"><summary>操作记录（最近50条）</summary><p v-for="e in record.events" :key="e.id">{{ formatTime(e.created_at) }} · {{ e.actor_name || '已停用账号' }} · {{ eventLabels[e.action] || e.action }}</p></details>
      </template>
      <template #footer><div v-if="record" class="drawer-footer"><span>{{ dirty ? '有未保存的填写内容' : '已同步' }}</span><el-button v-if="!editable && record.id" :disabled="busy" @click="download(record.id)">导出{{ ['draft','returned'].includes(record.status) ? '草稿' : '周表' }}</el-button><el-button v-if="editable" :disabled="busy || !dirty" @click="saveReport(false)">{{ dirty ? '保存草稿' : '已保存' }}</el-button><el-button v-if="editable" type="primary" :disabled="busy" @click="saveReport(true)">提交材料</el-button><el-button v-if="isOwner && record.status === 'submitted'" :disabled="busy" @click="act('withdraw')">撤回修改</el-button><el-button v-if="canReview && record.status === 'submitted'" :disabled="busy" @click="act('return')">退回补充</el-button><el-button v-if="canReview && record.status === 'submitted'" type="primary" :disabled="busy" @click="act('confirm')">确认材料</el-button><el-button v-if="canReview && record.status === 'confirmed'" :disabled="busy" @click="act('reopen')">重新打开</el-button></div></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import RawDutyWeekTable from '../components/RawDutyWeekTable.vue'
import RawDutySummary from '../components/RawDutySummary.vue'
import {editableReportView} from '../utils/raw-duty-editable-view.mjs'
import { rawDuty as api } from '../api/raw-duties'
import { dutyState } from '../utils/raw-duty-progress.mjs'
import {weekDays,weekMonths,checkFor,cadenceSummary} from '../utils/raw-duty-cadence-summary.mjs'
const labels={empty:'未开始',draft:'填写中',submitted:'已提交',returned:'需补充',confirmed:'已确认'}
const eventLabels={saved:'保存填写',submitted:'提交周材料',withdraw:'撤回修改',confirm:'确认材料',return:'退回补充',reopen:'重新打开',photo_added:'上传验证图片',photo_removed:'删除验证图片',photo_removed_admin:'管理员清理验证照片',ai_summary_generated:'生成 AI 周总结'}
const frequencies=['每班','每周','每月','持续开展']
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const monday=value=>{const d=new Date(value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return d.toISOString().slice(0,10)}
const week=ref(monday(new Date(Date.now()+8*3600000).toISOString().slice(0,10))),period=ref({start:'',end:''}),tab=ref('reports')
const context=ref({members:[],users:[],templates:[],results:[],canConfigure:false,canManageMembers:false,isReviewer:false}),rows=ref([]),selection=ref([]),search=ref(''),error=ref(''),loading=ref(false),busy=ref(false),exporting=ref(false),uploading=ref(false)
const availableTemplates=computed(()=>context.value.templates.filter(t=>Number(t.id)>0))
const ownerTab=ref('fill')
const ownMember=computed(()=>context.value.members.find(m=>m.user_id===context.value.userId&&m.active))
const filtered=computed(()=>rows.value.filter(r=>[r.name,r.position,r.team].join(' ').includes(search.value.trim())))
const exportIds=computed(()=>selection.value.filter(r=>r.canRead && r.reportId && ['submitted','confirmed'].includes(r.status)).map(r=>r.reportId))
const metrics=computed(()=>[{label:'本周人员',value:rows.value.length,color:'#6263a8'},{label:'待提交',value:rows.value.filter(r=>['empty','draft'].includes(r.status)).length,color:'#c77820'},{label:'已提交 / 已确认',value:rows.value.filter(r=>['submitted','confirmed'].includes(r.status)).length,color:'#16867e'},{label:'需补充',value:rows.value.filter(r=>r.status==='returned').length,color:'#c53d4f'}])
const editingTemplate=ref(false),templateTargetId=ref(0)
const memberDrafts=ref([]),templateId=ref(0),templateDraft=ref({title:'',entries:[]})
const generatingSummary=ref(false),summaryError=ref(''),summaryQuota=ref({limit:3,used:0,remaining:3,unlimited:false})
const showItem=ref(false)
const expandedDuties=ref([]),activeDuty=ref('')
const selectedDate=ref(''),frequencyFilter=ref('每班'),calendar=ref({})
const cadenceMode=computed(()=>record.value?.cadence?.version===2)
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10)
function itemCheck(item){return cadenceMode.value?checkFor(item,checks.value[item.id],selectedDate.value):checks.value[item.id]}
function editCheck(id){return itemCheck(record.value.template.entries.find(e=>e.id===id))}
function canEditItem(item){return !itemCheck(item)?.shared&&editable.value&&(!cadenceMode.value||item.frequency!=='每班'||calendar.value[selectedDate.value]==='work'&&selectedDate.value<=today)}
const reportStats=computed(()=>cadenceSummary(record.value?.template.entries||[],Object.values(checks.value),cadenceMode.value?{version:2,calendar:calendar.value}:null,record.value?.week_start||today,today))
async function chooseCell(item,day){selectedDate.value=day;frequencyFilter.value=item.frequency;if(!cadenceMode.value){await openDuty(item.id);return}if(item.frequency==='每班'&&(calendar.value[day]!=='work'||day>today)){activeDuty.value='';return}if(editable.value&&item.frequency!=='每班'&&!itemCheck(item).recordDate&&!itemCheck(item).shared&&day<=today)itemCheck(item).recordDate=day;await openDuty(item.id)}
function outsideExecutionDate(date,item){const day=localDate(date);return day>today||(item.frequency==='每月'?day.slice(0,7)!==selectedDate.value.slice(0,7):day<record.value.week_start||day>reportEnd.value)}
function setDayState(state){if(state==='rest'&&record.value.template.entries.filter(e=>e.frequency==='每班').some(e=>{const c=checkFor(e,checks.value[e.id],selectedDate.value);return c.result||c.note||c.photoIds?.length}))return ElMessage.warning('当日已有履职记录，请先清空并保存后再标记休息');calendar.value[selectedDate.value]=state;dirty.value=true;activeDuty.value=''}
async function openDuty(id){activeDuty.value=id;expandedDuties.value=[id];showItem.value=true}

const ownerEntries=computed(()=>record.value?.template.entries||[])
const ownerDailyTotal=computed(()=>calendar.value[selectedDate.value]==='rest'?0:ownerEntries.value.filter(e=>e.frequency==='每班').length)
const ownerDailyDone=computed(()=>ownerEntries.value.filter(e=>e.frequency==='每班'&&dutyState(itemCheck(e))==='done').length)
const ownerDailyAbnormal=computed(()=>ownerEntries.value.filter(e=>e.frequency==='每班'&&dutyState(itemCheck(e))==='abnormal').length)
const ownerPending=computed(()=>calendar.value[selectedDate.value]==='rest'?0:ownerEntries.value.filter(e=>e.frequency==='每班'&&['missing','evidence'].includes(dutyState(itemCheck(e)))).length)
const ownerGroups=computed(()=>{const out=[];for(const e of ownerEntries.value){if(e.frequency==='每班'&&calendar.value[selectedDate.value]==='rest')continue;let g=out.find(g=>g.name===e.category);if(!g)out.push(g={name:e.category,items:[]});g.items.push(e)}return out})
function ownerPeriodPending(f){return ownerEntries.value.filter(e=>e.frequency===f&&['missing','evidence'].includes(dutyState(itemCheck(e)))).length}
function ownerItemLabel(e){const c=itemCheck(e);if(!cadenceMode.value)return '原周记录：'+(c.result||'待填写');return c.result?(c.result==='未完成'?'未履职':c.result)+(c.recordDate?' · '+c.recordDate:''):e.frequency==='每班'?(selectedDate.value<today&&calendar.value[selectedDate.value]==='work'?'未履职 · 未记录':'待今日填报'):e.frequency==='每月'?'待本月填报':'待本周填报'}
async function openOwnerItem(e){frequencyFilter.value=e.frequency;if(cadenceMode.value&&e.frequency!=='每班'&&!itemCheck(e).recordDate&&!itemCheck(e).shared&&editable.value)itemCheck(e).recordDate=selectedDate.value;await openDuty(e.id)}
async function changeFillDate(day){if(busy.value)return;if(dirty.value)await saveReport(false);if(monday(day)!==week.value){week.value=monday(day);await refresh();await openOwn(false)}selectedDate.value=day}
async function reloadOwn(){if(!await allowLeave())return;summaryQuota.value=(await api.get('/summary-quota')).data;await openOwn(false)}
const showReport=ref(false),record=ref(null),checks=ref({}),summary=ref(''),feedback=ref(''),dirty=ref(false),photoUrls=ref({})
const dialogWidth='min(1500px, calc(100vw - 24px))'
const isOwner=computed(()=>record.value?.user_id===context.value.userId)
const editable=computed(()=>isOwner.value&&ownMember.value&&['draft','returned'].includes(record.value?.status))
const canReview=computed(()=>record.value&&!isOwner.value&&rows.value.find(r=>r.reportId===record.value.id)?.canReview)
const reportEnd=computed(()=>record.value?new Date(Date.parse(record.value.week_start+'T00:00:00Z')+6*86400000).toISOString().slice(0,10):'')
const activeEntry=computed(()=>record.value?.template.entries.find(e=>e.id===activeDuty.value))
const nextItem=computed(()=>{const entries=ownerTab.value==='fill'&&!context.value.isReviewer?ownerGroups.value.flatMap(g=>g.items):record.value?.template.entries.filter(e=>!cadenceMode.value||e.frequency===frequencyFilter.value)||[],index=entries.findIndex(e=>e.id===activeDuty.value);return entries.slice(index+1).find(e=>canEditItem(e)&&(!itemCheck(e).result||dutyState(itemCheck(e))==='evidence'))||null})
async function saveItem(next=false){if(busy.value)return;const nextId=next?nextItem.value?.id:null;busy.value=true;try{await persist(false);if(nextId){activeDuty.value=nextId;frequencyFilter.value=record.value.template.entries.find(e=>e.id===nextId).frequency;expandedDuties.value=[nextId];await nextTick();document.querySelector('.duty-item-dialog .el-dialog__body')?.scrollTo({top:0})}else showItem.value=false;ElMessage.success('已保存')}finally{busy.value=false}}
async function closeItem(done){if(busy.value)return;if(dirty.value&&editable.value){busy.value=true;try{await persist(false)}catch{return}finally{busy.value=false}}done()}
const groups=computed(()=>{const out=[];record.value?.template.entries.forEach((e,index)=>{if(e.id!==activeDuty.value)return;let g=out.find(g=>g.name===e.category);if(!g){g={name:e.category,items:[]};out.push(g)}g.items.push({...e,index})});return out})
function tagType(s){return {confirmed:'success',submitted:'primary',returned:'danger',draft:'warning',empty:'info'}[s]}
function formatTime(t){if(!t)return '—';return /Z$/.test(String(t))?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):String(t).replace('T',' ').slice(0,19)}
async function loadContext(){const {data}=await api.get('/context');context.value=data;summaryQuota.value=data.summaryQuota||summaryQuota.value;memberDrafts.value=data.users.map(u=>{const m=data.members.find(m=>m.user_id===Number(u.id));return {user_id:Number(u.id),name:u.name,position:m?.position_name||'工段长',team:m?.team_name||'',reviewerId:m?.reviewer_id||null,templateId:m?.template_id||null,active:m?m.active:false,revision:m?.revision||0}});if(!templateDraft.value.entries.length)loadTemplate(data.templates.find(t=>t.id)?.id||0)}
async function refresh(){loading.value=true;error.value='';try{const {data}=await api.get('/reports',{params:{week:week.value}});period.value=data.period;rows.value=data.items;selection.value=[]}catch(e){error.value=e.response?.data?.msg||'加载失败，请点击刷新重试'}finally{loading.value=false}}
async function changeWeek(v){if(!await allowLeave())return;week.value=monday(v);record.value=null;await refresh();if(ownMember.value&&!context.value.isReviewer)await openOwn(false)}
function loadTemplate(id){const t=availableTemplates.value.find(t=>t.id===id);templateId.value=t?.id||0;templateDraft.value=t?JSON.parse(JSON.stringify(t)):{title:'',entries:[]};templateTargetId.value=t?.id||0;editingTemplate.value=false}
async function beginTemplateEdit(){if(!templateId.value)return newTemplate();editingTemplate.value=true;templateTargetId.value=templateId.value}
async function newTemplate(){let value;try{({value}=await ElMessageBox.prompt('输入新模板名称','新建模板',{inputValue:'原粮工段长职责模板',inputPattern:/\S/,inputErrorMessage:'请输入名称'}))}catch{return}templateDraft.value={title:value.trim(),entries:[]};addDuty();templateTargetId.value=0;editingTemplate.value=true}
async function renameTemplate(){let value;try{({value}=await ElMessageBox.prompt('输入模板新名称','重命名',{inputValue:templateDraft.value.title,inputPattern:/\S/,inputErrorMessage:'请输入名称'}))}catch{return}busy.value=true;try{await api.put('/templates/'+templateId.value,{...templateDraft.value,title:value.trim(),ifMatch:templateDraft.value.etag});await loadContext();loadTemplate(templateId.value);ElMessage.success('已重命名')}finally{busy.value=false}}
async function deleteTemplate(){try{await ElMessageBox.confirm('删除“'+templateDraft.value.title+'”？历史周材料保留原模板；仍分配给人员的模板须先调整分配。','删除模板',{type:'warning'})}catch{return}busy.value=true;try{await api.delete('/templates/'+templateId.value,{data:{ifMatch:templateDraft.value.etag}});await loadContext();loadTemplate(context.value.templates.find(t=>t.id)?.id||0);ElMessage.success('模板已删除')}finally{busy.value=false}}
function addDuty(){templateDraft.value.entries.push({id:'custom-'+crypto.randomUUID(),category:'其他',title:'',frequency:'每周',evidence:''})}
async function saveTemplate(){busy.value=true;try{const {data}=templateTargetId.value?await api.put('/templates/'+templateTargetId.value,{...templateDraft.value,ifMatch:templateDraft.value.etag}):await api.post('/templates',templateDraft.value);await loadContext();loadTemplate(data.id);ElMessage.success('模板已保存，已生成的周材料保留原内容')}finally{busy.value=false}}
async function saveMember(row){if(!context.value.canManageMembers)return ElMessage.warning('仅系统管理员可分配履职人员与负责人');busy.value=true;try{await api.put('/members/'+row.user_id,{reviewerId:row.reviewerId,position:row.position,team:row.team,templateId:row.templateId,active:row.active,revision:row.revision});await loadContext();await refresh();ElMessage.success('人员分配已保存')}finally{busy.value=false}}
function revokePhotos(){Object.values(photoUrls.value).forEach(URL.revokeObjectURL);photoUrls.value={}}
const pendingPhotos=new Set()
async function acceptRecord(r){
 r=editableReportView(r,context.value.userId,Boolean(ownMember.value),today);
 if(record.value?.id!==r.id||record.value?.user_id!==r.user_id||record.value?.week_start!==r.week_start){selectedDate.value=weekDays(r.week_start).includes(today)?today:r.week_start;frequencyFilter.value='每班';activeDuty.value='';revokePhotos();expandedDuties.value=[r.template.entries.find(e=>['missing','evidence'].includes(dutyState(r.checks.find(c=>c.dutyId===e.id))))?.id||r.template.entries[0]?.id]}
 const stats=cadenceSummary(r.template.entries,r.checks,r.cadence,r.week_start,today);
 rows.value=rows.value.map(row=>row.userId===r.user_id?{...row,...stats,cadenceVersion:r.cadence?.version||1,status:r.status,filled:stats.progress.filled,total:stats.progress.total,updatedAt:r.updated_at,reportId:r.id,canRead:context.value.canViewDrafts||r.status!=='draft'||r.user_id===context.value.userId}:row);
 record.value=r;calendar.value={...(r.cadence?.calendar||{})};checks.value=Object.fromEntries(r.template.entries.map(e=>{
 const c=structuredClone(r.checks.find(c=>c.dutyId===e.id)||{dutyId:e.id,result:'',note:'',action:'',recordDate:'',photoIds:[]});
 const empty=()=>({result:'',note:'',action:'',recordDate:'',photoIds:[]});
 if(r.cadence?.version&&e.frequency==='每班')c.dailyRecords=weekDays(r.week_start).map(date=>({...empty(),date,...c.dailyRecords?.find(v=>v.date===date)}));
 if(r.cadence?.version&&e.frequency==='每月')c.monthlyRecords=weekMonths(r.week_start).map(month=>({...empty(),month,...c.monthlyRecords?.find(v=>v.month===month),dateRequired:true}));
 if(r.cadence?.version&&e.frequency!=='每班')c.dateRequired=true;return [e.id,c];}));summary.value=r.summary;feedback.value=r.feedback;dirty.value=false;
 for(const id of Object.keys(photoUrls.value))if(!r.photos.some(p=>p.id===Number(id))){URL.revokeObjectURL(photoUrls.value[id]);delete photoUrls.value[id]}
 for(const p of r.photos){const key=r.id+':'+p.id;if(photoUrls.value[p.id]||pendingPhotos.has(key))continue;pendingPhotos.add(key);api.get('/photos/'+p.id,{responseType:'blob'}).then(blob=>{if(record.value?.id===r.id&&record.value.photos.some(v=>v.id===p.id))photoUrls.value[p.id]=URL.createObjectURL(blob)}).catch(()=>{}).finally(()=>pendingPhotos.delete(key))}
}
async function openRow(row,day='',frequency='每班',showDialog=true){if(row.userId===context.value.userId&&!row.reportId)return openOwn(showDialog);if(!row.reportId&&!context.value.canViewDrafts)return;busy.value=true;try{const {data}=await api.get(row.reportId?'/reports/'+row.reportId:'/members/'+row.userId+'/report',{params:{week:week.value}});activeDuty.value='';showReport.value=showDialog;await acceptRecord(data);selectedDate.value=day||selectedDate.value;frequencyFilter.value=frequency}finally{busy.value=false}}
async function openOwn(showDialog=true){busy.value=true;try{const {data}=await api.post('/reports',{week:week.value});await refresh(false);showReport.value=showDialog!==false;await acceptRecord(data)}finally{busy.value=false}}
async function persist(submit){const {data}=await api.put('/reports/'+record.value.id,{revision:record.value.revision,checks:Object.values(checks.value),summary:summary.value,submit,calendar:calendar.value,upgradeCadence:record.value.pendingCadenceUpgrade===true});await acceptRecord(data);return data}
async function generateWeeklySummary(){if(!editable.value||busy.value)return;if(!summaryQuota.value.unlimited&&summaryQuota.value.remaining<=0)return ElMessage.warning('今日已达3次上限，请明天再试');if(summary.value.trim()){try{await ElMessageBox.confirm('根据最新已保存填报重新生成总结，替换当前总结内容？','重新生成周总结')}catch{return}}busy.value=true;generatingSummary.value=true;summaryError.value='';try{if(dirty.value)await persist(false);const id=record.value.id,revision=record.value.revision;const {data}=await api.post('/reports/'+id+'/summary',{revision},{timeout:75000});if(record.value?.id!==id||record.value.revision!==data.sourceRevision)throw new Error('填报材料已变化，请重新生成总结');summary.value=data.summary;summaryQuota.value=data.summaryQuota||summaryQuota.value;dirty.value=true;ElMessage.success('周总结已生成，请核对后保存')}catch(e){summaryError.value=e.response?.data?.msg||e.message||'周总结生成失败，原总结已保留';try{summaryQuota.value=(await api.get('/summary-quota')).data}catch{}}finally{generatingSummary.value=false;busy.value=false}}
async function saveReport(submit){if(submit){try{await ElMessageBox.confirm('提交后负责人可以查看本周明细和验证材料。确认提交？','提交周材料')}catch{return}}busy.value=true;try{await persist(submit);await refresh();ElMessage.success(submit?'本周材料已提交':'草稿已保存')}finally{busy.value=false}}
async function act(action){if(['withdraw','confirm'].includes(action)){try{await ElMessageBox.confirm(action==='withdraw'?'撤回后材料恢复为草稿，修改完成需重新提交。':'确认已查看本周材料？确认仅记录材料复核状态。','确认操作')}catch{return}}busy.value=true;try{const {data}=await api.post('/reports/'+record.value.id+'/action',{revision:record.value.revision,action,feedback:feedback.value});await acceptRecord(data);await refresh();ElMessage.success('操作已完成')}finally{busy.value=false}}
async function uploadPhoto(options,dutyId){busy.value=true;uploading.value=true;try{if(dirty.value)await persist(false);const previousIds=new Set(record.value.photos.map(p=>p.id));const body=new FormData();body.append('file',options.file);body.append('revision',record.value.revision);const {data}=await api.post('/reports/'+record.value.id+'/photos',body);await acceptRecord(data);const added=data.photos.filter(p=>!previousIds.has(p.id)).map(p=>p.id);if(dutyId&&checks.value[dutyId]){editCheck(dutyId).photoIds=[...new Set([...editCheck(dutyId).photoIds,...added])];dirty.value=true;await persist(false)}ElMessage.success('照片已添加到本项');options.onSuccess?.(data)}catch(e){options.onError?.(e)}finally{busy.value=false;uploading.value=false}}
async function removePhoto(id){if(Object.values(checks.value).some(c=>[c,...(c.dailyRecords||[]),...(c.monthlyRecords||[])].some(v=>(v.photoIds||[]).includes(id))))return ElMessage.warning('请先取消该材料与各事项的关联并保存');try{await ElMessageBox.confirm('删除这张尚未关联的验证图片？','删除材料')}catch{return}busy.value=true;try{if(dirty.value)await persist(false);const {data}=await api.delete(`/reports/${record.value.id}/photos/${id}`,{data:{revision:record.value.revision}});await acceptRecord(data)}finally{busy.value=false}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function download(id){if(id===record.value?.id&&dirty.value){try{await ElMessageBox.confirm('导出的是服务器已保存版本，是否先保存当前填写？','保存后导出')}catch{return}busy.value=true;try{await persist(false)}finally{busy.value=false}}exporting.value=true;try{saveBlob(await api.get(`/reports/${id}/export`,{responseType:'blob'}),`原粮周履职-${week.value}-${id}.xlsx`)}finally{exporting.value=false}}
async function exportBatch(){if(exportIds.value.length>20)return ElMessage.warning('每次最多选择20份材料');exporting.value=true;try{saveBlob(await api.post('/export',{reportIds:exportIds.value},{responseType:'blob'}),`原粮周材料-${week.value}.zip`)}finally{exporting.value=false}}
function outsideWeek(d){const s=localDate(d);return s<record.value?.week_start||s>reportEnd.value}
async function allowLeave(){if(busy.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('当前填写尚未保存，确定放弃这些修改？','未保存内容',{confirmButtonText:'放弃修改',cancelButtonText:'继续填写'});return true}catch{return false}}
async function closeReport(done){if(!await allowLeave())return;dirty.value=false;showItem.value=false;done()}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(allowLeave)
